//! The reindex function (navigation.md 2.2 and 3): ticket files moved to their computed paths and
//! the generated set rendered, all in memory.
//!
//! A pure function of the branch tree and the frob version: no clock, no I/O, stable order. A moved
//! ticket keeps its bytes, so its blob id is unchanged and the replay check (TICK007) can compare
//! whole-tree ids. Generated pages come from [`Generator`] functions the caller supplies; every
//! previously generated file (first line carries the `GENERATED by frob` marker) is dropped first,
//! so pages for tickets that no longer exist disappear.
// frob:ticket 01M3ZX85S7ASFGT31GDYMRB5JX

use std::collections::BTreeMap;

use crate::doc;
use crate::error::{LedgerError, Result};
use crate::id::{EventId, TicketId};
use crate::layout::{EVENTS_DIR, is_branch_ticket_candidate, peek_ticket_id};
use crate::path_fn::{PathTicket, ticket_paths};

/// A ticket-branch tree held in memory: branch-relative path to file bytes, in path order.
pub type Tree = BTreeMap<String, Vec<u8>>;

/// First-line prefix that marks a file as generated (navigation.md 3.3).
pub const GENERATED_MARKER_PREFIX: &str = "<!-- GENERATED by frob";

/// What a [`Generator`] sees: the tree with tickets already at their computed paths.
#[derive(Debug)]
pub struct GenInput<'a> {
    /// The tree after moves, without any previously generated file.
    pub tree: &'a Tree,
    /// The frob version the output is rendered for.
    pub version: &'a str,
    /// `[tickets] handle_min_len`, for pages that print handles.
    pub handle_min_len: usize,
    /// Newest event ULID in the tree (the "as of" line), `None` for an empty ledger.
    pub as_of: Option<&'a str>,
    /// Every ticket with the path it now lives at.
    pub paths: &'a BTreeMap<TicketId, String>,
}

/// A page renderer: returns `(path, bytes)` pairs. Must be a pure function of its input.
pub type Generator = fn(&GenInput<'_>) -> Vec<(String, Vec<u8>)>;

/// Settings of one reindex run.
#[derive(Debug, Clone, Copy)]
pub struct ReindexOptions<'a> {
    /// The frob version recorded in the `Frob-Reindex` trailer.
    pub version: &'a str,
    /// `[tickets] handle_min_len`.
    pub handle_min_len: usize,
    /// Page renderers, run in order; later output replaces earlier on the same path.
    pub generators: &'a [Generator],
}

/// One ticket file moved by a reindex.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Move {
    /// Old branch-relative path.
    pub from: String,
    /// New branch-relative path.
    pub to: String,
}

/// The result of a reindex.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Reindexed {
    /// The complete tree after the reindex.
    pub tree: Tree,
    /// Ticket files that moved, in old-path order.
    pub moves: Vec<Move>,
    /// Newest event ULID the run saw.
    pub as_of: Option<String>,
}

/// The id of a blob: the blake3 hex of its bytes, so a moved file keeps it.
#[must_use]
pub fn blob_id(bytes: &[u8]) -> String {
    blake3::hash(bytes).to_hex().to_string()
}

/// The id of a tree: a hash over every path and blob id in path order, so equal ids mean equal bytes.
#[must_use]
pub fn tree_id(tree: &Tree) -> String {
    let mut h = blake3::Hasher::new();
    for (path, bytes) in tree {
        h.update(&(path.len() as u64).to_le_bytes());
        h.update(path.as_bytes());
        h.update(blob_id(bytes).as_bytes());
    }
    h.finalize().to_hex().to_string()
}

/// Whether `bytes` start with the generated-file marker.
fn is_generated(bytes: &[u8]) -> bool {
    bytes.starts_with(GENERATED_MARKER_PREFIX.as_bytes())
}

/// The newest event ULID among `.events/<ULID>/<event>.toml` files.
fn newest_event(tree: &Tree) -> Option<String> {
    let prefix = format!("{EVENTS_DIR}/");
    tree.keys()
        .filter_map(|p| p.strip_prefix(&prefix))
        .filter_map(|rest| rest.rsplit('/').next())
        .filter_map(|name| name.strip_suffix(".toml"))
        .filter_map(|stem| stem.parse::<EventId>().ok())
        .max()
        .map(|id| id.to_string())
}

/// Move every ticket file of `tree` to its computed path and render the generated set.
///
/// # Errors
///
/// [`LedgerError::Malformed`] when a ticket file does not parse, two files carry one id, or a
/// computed path is taken by a file that is neither a ticket nor generated.
pub fn reindex(tree: &Tree, opts: &ReindexOptions<'_>) -> Result<Reindexed> {
    // Split the tree into tickets, previously generated pages and everything else.
    let mut tickets: BTreeMap<TicketId, (String, PathTicket)> = BTreeMap::new();
    let mut rest = Tree::new();
    for (path, bytes) in tree {
        if is_generated(bytes) {
            continue;
        }
        let text = std::str::from_utf8(bytes).ok();
        let is_ticket = is_branch_ticket_candidate(path) && text.and_then(peek_ticket_id).is_some();
        if !is_ticket {
            rest.insert(path.clone(), bytes.clone());
            continue;
        }
        let parsed = doc::parse(path, text.unwrap_or_default())?;
        let f = parsed.front;
        let pt = PathTicket {
            id: f.id,
            ty: f.ty,
            title: f.title,
            parent: f.parent,
        };
        if let Some((other, _)) = tickets.insert(f.id, (path.clone(), pt)) {
            return Err(LedgerError::malformed(
                path.clone(),
                format!("ticket {} is also at {other}", f.id),
            ));
        }
    }

    let list: Vec<PathTicket> = tickets.values().map(|(_, t)| t.clone()).collect();
    let paths = ticket_paths(&list, opts.handle_min_len);

    let mut out = rest;
    let mut moves = Vec::new();
    for (id, (old, _)) in &tickets {
        let new = &paths[id];
        if out.contains_key(new) {
            return Err(LedgerError::malformed(
                new.clone(),
                format!("computed path of ticket {id} is taken by a file that is not a ticket"),
            ));
        }
        out.insert(new.clone(), tree[old].clone());
        if old != new {
            moves.push(Move {
                from: old.clone(),
                to: new.clone(),
            });
        }
    }
    moves.sort_by(|a, b| a.from.cmp(&b.from));

    let as_of = newest_event(&out);
    // The generators borrow `out` and finish before any page is inserted, so no tree copy.
    let generated: Vec<(String, Vec<u8>)> = {
        let input = GenInput {
            tree: &out,
            version: opts.version,
            handle_min_len: opts.handle_min_len,
            as_of: as_of.as_deref(),
            paths: &paths,
        };
        opts.generators.iter().flat_map(|g| g(&input)).collect()
    };
    for (path, bytes) in generated {
        out.insert(path, bytes);
    }
    Ok(Reindexed {
        tree: out,
        moves,
        as_of,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::model::{Category, Class, Frontmatter, Priority, Stamp, TicketType};

    fn ticket(ty: TicketType, title: &str, parent: Option<TicketId>) -> (TicketId, String) {
        let id = TicketId::mint();
        let front = Frontmatter {
            id,
            title: title.into(),
            ty,
            flavour: None,
            category: Category::Todo,
            outcome: None,
            priority: Priority::High,
            class: Class::Standard,
            due: None,
            points: None,
            parent,
            reporter: "t".into(),
            assignee: None,
            created: Stamp::from_unix(1_790_000_000),
            updated: Stamp::from_unix(1_790_000_000),
            persona: None,
            capability: None,
            outcome_text: None,
            idempotency_key: None,
            aliases: vec![],
            labels: vec![],
            scope: vec![],
            links: vec![],
            acceptance: vec![],
        };
        let text = doc::render(&crate::model::Ticket {
            front,
            body: "body".into(),
        })
        .unwrap();
        (id, text)
    }

    fn opts(generators: &[Generator]) -> ReindexOptions<'_> {
        ReindexOptions {
            version: "9.9.9",
            handle_min_len: 7,
            generators,
        }
    }

    fn stamp_page(i: &GenInput<'_>) -> Vec<(String, Vec<u8>)> {
        let line = format!(
            "{GENERATED_MARKER_PREFIX} v{}: DO NOT EDIT -->\nas of {}\n{} files\n",
            i.version,
            i.as_of.unwrap_or("none"),
            i.tree.len()
        );
        vec![("indexes/page.md".into(), line.into_bytes())]
    }

    fn sample() -> (Tree, TicketId, TicketId) {
        let (epic, epic_text) = ticket(TicketType::Epic, "Navigation", None);
        let (task, task_text) = ticket(TicketType::Task, "New title here", Some(epic));
        let (_, other_text) = ticket(TicketType::Task, "Stays put", Some(epic));
        let mut t = Tree::new();
        t.insert("navigation/EPIC.md".into(), epic_text.into_bytes());
        // The decision commit refolded the title; the file still sits at the old slug.
        t.insert("navigation/old-title.md".into(), task_text.into_bytes());
        t.insert("navigation/stays-put.md".into(), other_text.into_bytes());
        t.insert(
            ".events/01M3ZX85S7ASFGT31GDYMRB5JX/01M3ZX85S7ASFGT31GDYMRB5JY.toml".into(),
            b"x".to_vec(),
        );
        (t, epic, task)
    }

    #[test]
    fn a_retitled_ticket_is_renamed_with_its_blob_id_and_nothing_else_moves() {
        let (tree, _, task) = sample();
        let before = blob_id(&tree["navigation/old-title.md"]);
        let out = reindex(&tree, &opts(&[])).unwrap();
        assert_eq!(
            out.moves,
            vec![Move {
                from: "navigation/old-title.md".into(),
                to: "navigation/new-title-here.md".into()
            }],
            "ticket {task}"
        );
        assert!(!out.tree.contains_key("navigation/old-title.md"));
        assert_eq!(blob_id(&out.tree["navigation/new-title-here.md"]), before);
        assert_eq!(out.tree.len(), tree.len());
        assert_eq!(
            out.tree["navigation/stays-put.md"],
            tree["navigation/stays-put.md"]
        );
    }

    #[test]
    fn reindexing_twice_gives_equal_tree_ids_and_generated_pages_are_replaced() {
        let (tree, _, _) = sample();
        let gens: &[Generator] = &[stamp_page];
        let once = reindex(&tree, &opts(gens)).unwrap();
        let twice = reindex(&once.tree, &opts(gens)).unwrap();
        assert_eq!(tree_id(&once.tree), tree_id(&twice.tree));
        assert!(twice.moves.is_empty());
        let page = String::from_utf8(twice.tree["indexes/page.md"].clone()).unwrap();
        assert!(page.contains("as of 01M3ZX85S7ASFGT31GDYMRB5JY"), "{page}");
        // A stale generated page of the input is dropped, not carried over.
        let mut stale = tree.clone();
        stale.insert(
            "old/README.md".into(),
            format!("{GENERATED_MARKER_PREFIX} v1 -->\n").into_bytes(),
        );
        assert!(
            !reindex(&stale, &opts(&[]))
                .unwrap()
                .tree
                .contains_key("old/README.md")
        );
    }

    #[test]
    fn a_changed_input_changes_the_tree_id() {
        let (mut tree, _, _) = sample();
        let a = tree_id(&reindex(&tree, &opts(&[])).unwrap().tree);
        tree.insert("navigation/stays-put.md".into(), {
            let mut b = tree["navigation/stays-put.md"].clone();
            b.extend_from_slice(b"\nmore");
            b
        });
        assert_ne!(a, tree_id(&reindex(&tree, &opts(&[])).unwrap().tree));
    }

    #[test]
    fn a_duplicate_ticket_id_is_refused() {
        let (mut tree, _, _) = sample();
        let dup = tree["navigation/stays-put.md"].clone();
        tree.insert("navigation/copy.md".into(), dup);
        assert!(reindex(&tree, &opts(&[])).is_err());
    }
}
